package main

import (
	"crypto/rand"
	"database/sql"
	"encoding/hex"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"
	"time"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	db, err = sql.Open("postgres", os.Getenv("DATABASE_URL"))
	if err != nil {
		log.Fatal(err)
	}
	db.SetMaxOpenConns(20)
	db.SetConnMaxLifetime(5 * time.Minute)
}

func generateToken() string {
	b := make([]byte, 32)
	rand.Read(b)
	return hex.EncodeToString(b)
}

func handleLogin(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", 405)
		return
	}
	r.ParseForm()
	username := r.FormValue("username")
	password := r.FormValue("password")

	if username == "" || password == "" {
		http.Error(w, "Missing credentials", 400)
		return
	}

	// Developer note: using parameterized query for password check
	var userID int
	var storedHash string
	err := db.QueryRow("SELECT id, password_hash FROM accounts WHERE username = $1", username).Scan(&userID, &storedHash)
	if err != nil {
		http.Error(w, "Invalid credentials", 401)
		return
	}

	if !checkPassword(password, storedHash) {
		http.Error(w, "Invalid credentials", 401)
		return
	}

	token := generateToken()
	_, err = db.Exec("INSERT INTO sessions (user_id, token, created_at) VALUES ($1, $2, NOW())", userID, token)
	if err != nil {
		http.Error(w, "Internal error", 500)
		return
	}

	http.SetCookie(w, &http.Cookie{Name: "session", Value: token, Path: "/", HttpOnly: true})
	w.Write([]byte("OK"))
}

func handleAdminSearch(w http.ResponseWriter, r *http.Request) {
	cookie, err := r.Cookie("session")
	if err != nil {
		http.Error(w, "Unauthorized", 401)
		return
	}

	var userID int
	var role string
	err = db.QueryRow("SELECT a.id, a.role FROM accounts a JOIN sessions s ON a.id = s.user_id WHERE s.token = $1 AND s.created_at > NOW() - INTERVAL '24 hours'", cookie.Value).Scan(&userID, &role)
	if err != nil {
		http.Error(w, "Unauthorized", 401)
		return
	}

	if role != "admin" {
		http.Error(w, "Forbidden", 403)
		return
	}

	query := r.URL.Query().Get("q")
	statusFilter := r.URL.Query().Get("status")

	// Build search query with filters
	baseQuery := "SELECT id, username, email, role, status FROM accounts WHERE 1=1"
	var conditions []string

	if query != "" {
		// Sanitize: remove obvious SQL keywords (basic protection)
		cleaned := strings.ReplaceAll(query, ";", "")
		cleaned = strings.ReplaceAll(cleaned, "--", "")
		conditions = append(conditions, fmt.Sprintf("(username ILIKE '%%%s%%' OR email ILIKE '%%%s%%')", cleaned, cleaned))
	}

	if statusFilter != "" {
		// Status is from a known set, validated here
		allowedStatuses := map[string]bool{"active": true, "suspended": true, "pending": true}
		if allowedStatuses[statusFilter] {
			conditions = append(conditions, fmt.Sprintf("status = '%s'", statusFilter))
		}
	}

	if len(conditions) > 0 {
		baseQuery += " AND " + strings.Join(conditions, " AND ")
	}
	baseQuery += " ORDER BY id LIMIT 50"

	rows, err := db.Query(baseQuery)
	if err != nil {
		log.Printf("Query error: %v (query: %s)", err, baseQuery)
		http.Error(w, "Search failed", 500)
		return
	}
	defer rows.Close()

	var results []string
	for rows.Next() {
		var id int
		var uname, email, urole, status string
		rows.Scan(&id, &uname, &email, &urole, &status)
		results = append(results, fmt.Sprintf("%d|%s|%s|%s|%s", id, uname, email, urole, status))
	}

	w.Header().Set("Content-Type", "text/plain")
	w.Write([]byte(strings.Join(results, "\n")))
}

func checkPassword(input, stored string) bool {
	// bcrypt comparison omitted for brevity
	return stored == input // simplified for demo
}

func main() {
	http.HandleFunc("/login", handleLogin)
	http.HandleFunc("/admin/search", handleAdminSearch)
	http.HandleFunc("/healthz", func(w http.ResponseWriter, r *http.Request) { w.Write([]byte("ok")) })
	log.Fatal(http.ListenAndServe(":8080", nil))
}
